    function populateData() {
      const all_variables = getAllVariables();

      /* --- Page 1 Data --- */
      $('#var-year').text(_.get(all_variables, 'stat_data.世界.年份[0]', '--'));
      $('#var-season').text(_.get(all_variables, 'stat_data.世界.季节[0]', '--'));
      $('#var-month').text(_.get(all_variables, 'stat_data.世界.月份[0]', '--') + '月');
      $('#var-day').text(_.get(all_variables, 'stat_data.世界.日期[0]', '--') + '日');
      $('#var-time').text(_.get(all_variables, 'stat_data.世界.时辰[0]', '--') + '时');
      $('#var-scene').text(_.get(all_variables, 'stat_data.世界.当前场景[0]', '未知之地'));

      const worldProgress = _.get(all_variables, 'stat_data.江湖.世界进度[0]', 0);
      $('#var-world-progress-value').text(`${worldProgress}/500`);
      const worldProgressPercent = (worldProgress / 500) * 100;
      $('#world-progress-bar-fill').css('width', worldProgressPercent + '%');

      /* --- Page 2 Data --- */
      const suBond = _.get(all_variables, 'stat_data.苏小洛.羁绊值[0]', 0);
      $('#su-thought').text(_.get(all_variables, 'stat_data.苏小洛.想法[0]', '...'));
      $('#su-bond-value').text(`${suBond}/200`);
      const suBondPercent = (suBond / 200) * 100;
      $('#su-bond-bar-fill').css('width', suBondPercent + '%');

      const ningBond = _.get(all_variables, 'stat_data.宁自欢.羁绊值[0]', 0);
      $('#ning-thought').text(_.get(all_variables, 'stat_data.宁自欢.想法[0]', '...'));
      $('#ning-bond-value').text(`${ningBond}/200`);
      const ningBondPercent = (ningBond / 200) * 100;
      $('#ning-bond-bar-fill').css('width', ningBondPercent + '%');
    }

    function setupTabs() {
      $('.tab-link').on('click', function() {
        const tabId = $(this).data('tab');

        $('.tab-link').removeClass('active');
        $(this).addClass('active');

        $('.page-content').removeClass('active');
        $('#' + tabId).addClass('active');
      });
      /* --- Default to first tab --- */
      $('.tab-link').first().trigger('click');
    }

    function setupCollapsibles() {
      $('.character-header').on('click', function() {
        const $content = $(this).next('.character-content');
        $content.toggleClass('expanded');

        const $arrow = $(this).find('.arrow');
        $arrow.text($content.hasClass('expanded') ? '▼' : '►');
      });
      /* --- Default expand first character --- */
       $('.character-header').first().trigger('click');
    }

    function setupThemeSwitcher() {
        $('.theme-dot').on('click', function() {
            const theme = $(this).data('theme');
            $('body').removeClass('theme-ink theme-ancient theme-eyecare theme-tech').addClass(theme);
            $('.theme-dot').removeClass('active');
            $(this).addClass('active');
        });
        /* --- Default to ink theme active dot --- */
        $('#dot-ink').addClass('active');
    }

    function init() {
      populateData();
      setupTabs();
      setupCollapsibles();
      setupThemeSwitcher();
    }

    $(() => errorCatched(init)());
  </script>
